export function rejoinChampSeventhBreathConsistent (e) {
  if (!e || typeof e !== 'object') return false
  const ok = (n) => Number.isInteger(n) && n >= 0 && n <= 86399
  return Boolean(e.back && e.prev && e.cur &&
    ok(e.back.rejoinChampSeventhBreath) && ok(e.prev.rejoinChampSeventhBreath) && ok(e.cur.rejoinChampSeventhBreath))
}

